};
using BucketPtr = std::shared_ptr<Bucket>;

std::unique_ptr<std::map<float, BucketPtr>> make_balanced_view_map(int num_buckets, int partitions_per_bucket, std::vector<BucketPtr>& buckets_out) {
    if (num_buckets <= 0 || partitions_per_bucket <= 0) {
        throw std::invalid_argument("num_buckets and partitions_per_bucket must be positive");
    }

    auto partition_map = std::make_unique<std::map<float, BucketPtr>>();
    buckets_out.clear();
    buckets_out.reserve(num_buckets);

    float total_partitions = (float)num_buckets * partitions_per_bucket;
    float step = 1.0f / total_partitions;

    for (int i = 0; i < num_buckets; ++i) {
        std::vector<float> points;
        points.reserve(partitions_per_bucket);

        for (int j = 0; j < partitions_per_bucket; ++j) {
            // Distribute points uniformly: 
            // Bucket 0: 0, num_buckets, 2*num_buckets...
            // Bucket 1: 1, num_buckets+1, 2*num_buckets+1...
            // This ensures equidistant partition points across the unit circle.
            float point = (float)(i + j * num_buckets) * step;
            if (point >= 1.0f) point -= 1.0f; // Wrap around unit circle
            points.push_back(point);
